item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic sel_b1,
    input  logic sel_b2,
    output logic out_assign,
    output logic out_always
);
    assign out_assign = (sel_b1 && sel_b2) ? b : a;

    always_comb begin
        if (sel_b1 && sel_b2)
            out_always = b;
        else
            out_always = a;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic a, b, sel_b1, sel_b2;
    wire out_assign, out_always;
    logic expected;
    integer i;

    TopModule dut (.*);

    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            {a, b, sel_b1, sel_b2} = i[3:0];
            #1;
            expected = ((i & 3) == 3) ? b : a;
            if (out_assign "'!== expected || out_always !== expected)
                $fatal(1, "FAIL inputs=%b outputs=%b%b expected=%b",
                       {a,b,sel_b1,sel_b2}, out_assign, out_always, expected);
        end
        $display("PASS: all 16 binary input combinations");
        $finish;
    end

    initial begin
        #100;
        $fatal(1, "FAIL: timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

